WITH SessionStats AS (SELECT session_id, ROUND((100 * SUM(CASE WHEN event_type = 'add_to_cart' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_add_to_cart, ROUND((100 * SUM(CASE WHEN event_type = 'search' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_search FROM web_events WHERE duration_sec > 163 GROUP BY session_id) SELECT s.started_at, S.pct_add_to_cart, S.pct_search FROM sessions s INNER JOIN SessionStats S ON s.id = S.session_id WHERE S.pct_add_to_cart >= 31
